import React, { useMemo } from 'react';
import { useCalendarGridInteraction } from './useCalendarGridInteraction';
import { clsx } from "clsx";
import { twMerge } from "tailwind-merge";
import { formatHourAmpm, resolveHourStatus, getAttendanceBadge } from './calendarUtils';

function cn(...inputs) {
    return twMerge(clsx(inputs));
}

export default function CalendarGrid({
    courts = [],
    openHour = 7,
    closeHour = 22,
    bookings = {},
    slots = [],
    currentDate = new Date(),
    onTimeSelect,
    onBookingClick,
    isEditMode = false,
    modifiedSlots = {},
    onSlotMove,
    privacyMode = "staff",
}) {
    const currentYMD = currentDate.toLocaleDateString("en-CA");
    const isClientView = privacyMode === "client";

    const effectiveSlots = useMemo(() => {
        const baseSlots = slots.filter(slot => {
            return slot.date === currentYMD && slot.status === "ACTIVE";
        });

        if (!isEditMode) return baseSlots;

        return baseSlots.map(s => {
            if (modifiedSlots[s.slotId]) {
                return { ...s, ...modifiedSlots[s.slotId] };
            }
            return s;
        });
    }, [slots, currentYMD, isEditMode, modifiedSlots]);

    const timeSlots = useMemo(() => {
        const chunks = [];
        for (let h = openHour; h < closeHour; h++) {
            chunks.push({ hour: h, minute: 0, label: formatHourAmpm(h) });
        }
        return chunks;
    }, [openHour, closeHour]);

    const {
        handleMouseDown,
        handleMouseEnter,
        handleMouseUp,
        handleTouchStart,
        handleTouchMove,
        handleTouchEnd,
        selectionBox
    } = useCalendarGridInteraction({
        courts,
        onSelectionComplete: onTimeSelect
    });

    const isSelected = (courtId, timeVal) => {
        if (!selectionBox) return false;
        const s = selectionBox.start;
        const e = selectionBox.end;

        const cIdx = courts.findIndex(c => String(c.id) === String(courtId));
        const sIdx = courts.findIndex(c => String(c.id) === String(s.courtId));
        const eIdx = courts.findIndex(c => String(c.id) === String(e.courtId));

        const minC = Math.min(sIdx, eIdx);
        const maxC = Math.max(sIdx, eIdx);

        const minT = Math.min(s.time, e.time);
        const maxT = Math.max(s.time, e.time);

        return (cIdx >= minC && cIdx <= maxC) && (timeVal >= minT && timeVal <= maxT);
    };

    const handleDragStart = (e, slotId) => {
        if (!isEditMode) return;
        e.dataTransfer.setData("text/plain", slotId);
        e.dataTransfer.effectAllowed = "move";
    };

    const handleDragOver = (e) => {
        if (!isEditMode) return;
        e.preventDefault();
        e.dataTransfer.dropEffect = "move";
    };

    const handleDrop = (e, courtId, timeInMinutes) => {
        if (!isEditMode) return;
        e.preventDefault();
        const slotId = e.dataTransfer.getData("text/plain");
        if (onSlotMove) {
            onSlotMove(slotId, timeInMinutes, courtId);
        }
    };

    return (
        <div
            className="select-none overflow-auto pb-20 relative bg-white h-full"
            onMouseUp={handleMouseUp}
            onMouseLeave={handleMouseUp}
        >
            <div className="min-w-[1000px]">
                {/* Header Row */}
                <div className="flex border-b-2 border-slate-300 sticky top-0 bg-white z-20 shadow-sm ml-24">
                    {timeSlots.map((slot, i) => (
                        <div key={i} className="flex-1 min-w-[60px] h-10 border-r border-slate-300 relative flex items-end pb-1 justify-center">
                            {slot.label && (
                                <span className="text-[10px] font-semibold text-slate-600 transform -translate-x-1/2 absolute left-0 bottom-1 bg-white px-1 whitespace-nowrap">
                                    {slot.label}
                                </span>
                            )}
                        </div>
                    ))}
                </div>

                {/* Grid Rows */}
                <div className="relative">
                    {courts.map(court => (
                        <div key={court.id} className="flex h-24 border-b-2 border-slate-300 group">
                            {/* Court Label */}
                            <div className="w-24 flex-shrink-0 sticky left-0 bg-white z-10 border-r-2 border-slate-300 flex items-center justify-center font-bold text-slate-800 shadow-[4px_0_24px_-12px_rgba(0,0,0,0.1)]">
                                {court.name}
                            </div>

                            {/* Cells */}
                            {timeSlots.map((timeSlot, i) => {
                                const timeInMinutes = timeSlot.hour * 60 + timeSlot.minute;

                                const { kind, booking: parentBooking } = resolveHourStatus({
                                    slots: effectiveSlots,
                                    bookings,
                                    courtId: court.id,
                                    dateYmd: currentYMD,
                                    hour: timeSlot.hour,
                                });

                                const activeSlot = kind !== "available"
                                    ? effectiveSlots.find(s => {
                                        if (String(s.courtId) !== String(court.id)) return false;
                                        return timeInMinutes >= s.startTime && timeInMinutes < s.endTime;
                                    })
                                    : null;

                                const selected = isSelected(court.id, timeInMinutes);
                                const isStart = activeSlot && activeSlot.startTime === timeInMinutes;

                                let cellStyle = "";
                                let label = "";
                                let isModified = activeSlot && modifiedSlots[activeSlot.slotId];

                                let attendanceBadge = null;
                                if (parentBooking) {
                                    if (parentBooking.type === "OPEN_PLAY_BLOCK") {
                                        cellStyle = "bg-slate-200 text-slate-700 border-slate-400 border-l-4 border-l-slate-500";
                                        label = "Unavailable";
                                    } else {
                                        label = isClientView
                                            ? "BOOKED"
                                            : (parentBooking.renter?.name || "Booked");

                                        const allBookingSlots = slots.filter(s => s.bookingId === parentBooking.id);
                                        const slotTotal = allBookingSlots.reduce((sum, s) => sum + (s.price || 0), 0);
                                        const pSum = parentBooking.paymentSummary || {};
                                        const calculatedTotal = (pSum.totalAmount > 0) ? pSum.totalAmount : slotTotal;
                                        const isPaid = (pSum.amountPaid || 0) >= (calculatedTotal || 0) && (calculatedTotal > 0);
                                        const isPartial = !isPaid && (pSum.amountPaid || 0) > 0;
                                        attendanceBadge = getAttendanceBadge(parentBooking.renter?.attendance);

                                        if (isPaid) {
                                            cellStyle = "bg-emerald-100 text-emerald-900 border-emerald-400 border-2";
                                        } else if (isPartial) {
                                            cellStyle = "bg-yellow-100 text-yellow-900 border-yellow-400 border-l-4 border-l-yellow-500";
                                        } else {
                                            cellStyle = "bg-red-50 text-red-900 border-red-400 border-l-4 border-l-red-500";
                                        }
                                        if (attendanceBadge) {
                                            cellStyle = cn(cellStyle, attendanceBadge.stripeClass);
                                        }
                                    }

                                    if (isModified) {
                                        cellStyle = "bg-blue-100 text-blue-900 border-blue-400 ring-2 ring-blue-500/20 z-10";
                                    }
                                }

                                const isWebsiteLocked = parentBooking?.source === 'WEBSITE';
                                const canDragSlot = isEditMode && !isWebsiteLocked;

                                return (
                                    <div
                                        key={i}
                                        className={cn(
                                            "flex-1 min-w-[60px] border-r border-slate-300 relative transition-colors duration-75",
                                            !activeSlot && selected && "bg-emerald-500/20",
                                            !activeSlot && !selected && !isEditMode && "hover:bg-slate-50/80",
                                            isEditMode && !activeSlot && "hover:bg-blue-50/50"
                                        )}
                                        onTouchStart={() => !isEditMode && !activeSlot && handleTouchStart(court.id, timeInMinutes)}
                                        onTouchMove={handleTouchMove}
                                        onTouchEnd={handleTouchEnd}
                                        data-court-id={court.id}
                                        data-time={timeInMinutes}
                                        onMouseDown={() => !isEditMode && !activeSlot && handleMouseDown(court.id, timeInMinutes)}
                                        onMouseEnter={() => !isEditMode && !activeSlot && handleMouseEnter(court.id, timeInMinutes)}
                                        onDragOver={handleDragOver}
                                        onDrop={(e) => handleDrop(e, court.id, timeInMinutes)}
                                    >
                                        {!activeSlot && !isEditMode && (
                                            <span className="absolute inset-0 flex items-center justify-center text-[9px] font-medium text-slate-300/80 pointer-events-none select-none">
                                                Vacant
                                            </span>
                                        )}

                                        {activeSlot && parentBooking && (
                                            <div
                                                draggable={canDragSlot}
                                                onDragStart={(e) => {
                                                    if (!canDragSlot) {
                                                        e.preventDefault();
                                                        return;
                                                    }
                                                    handleDragStart(e, activeSlot.slotId);
                                                }}
                                                title={isWebsiteLocked && isEditMode ? 'Website booking — locked' : undefined}
                                                onClick={(e) => {
                                                    e.stopPropagation();
                                                    if (!isEditMode) {
                                                        onBookingClick && onBookingClick(parentBooking.id);
                                                    }
                                                }}
                                                className={cn(
                                                    "absolute inset-0 m-0.5 rounded flex items-center justify-center text-[10px] font-bold truncate px-1 shadow-sm transition-all border-2",
                                                    cellStyle,
                                                    !isEditMode && "cursor-pointer hover:brightness-95",
                                                    canDragSlot && "cursor-move hover:scale-[1.02] hover:shadow-md hover:ring-2 ring-emerald-400/50 z-20",
                                                    isEditMode && isWebsiteLocked && "cursor-not-allowed opacity-80"
                                                )}
                                                style={{ zIndex: isModified ? 30 : 1 }}
                                            >
                                                {isStart && (
                                                    <>
                                                        {label}
                                                        {attendanceBadge && !isClientView && (
                                                            <span className={cn("ml-1 text-[8px] rounded px-1 uppercase tracking-wide", attendanceBadge.badgeClass)}>
                                                                {attendanceBadge.short}
                                                            </span>
                                                        )}
                                                        {isModified && <span className="ml-1 text-[8px] bg-blue-600 text-white rounded px-1">MOD</span>}
                                                    </>
                                                )}
                                            </div>
                                        )}
                                    </div>
                                );
                            })}
                        </div>
                    ))}
                </div>
            </div>
        </div>
    );
}
